const AnimatedChecklist: React.FC<ComponentNameProps> = ({
  backgroundColor = "#101D42",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#2B66FF",
  iconColor = "#1A2B56",
  items = [
    {
      text: "We'll Share Practical Strategies to Strengthen Your Accreditation",
      icon: "target",
      startFrame: 0,
    },
    {
      text: "Improve Your Business Performance",
      icon: "chart",
      startFrame: 90,
    },
    {
      text: "Build a Clear Roadmap for Sustainable Growth",
      icon: "path",
      startFrame: 126,
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const squareSize = 140 * s;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 60 * s,
          width: 900 * s,
          margin: "0 auto",
          justifyContent: "center",
          height: "100%",
          transition: "none",
        }}
      >
        {items.map((item, index) => {
          // Main entrance animation
          const progress = spring({
            fps,
            frame: frame - item.startFrame,
            config: { damping: 14 },
          });
          const slideY = interpolate(progress, [0, 1], [60 * s, 0]);
          const baseOpacity = interpolate(
            frame - item.startFrame,
            [0, 15],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // Dimming effect when subsequent items appear
          let dimFactor = 1;
          if (index < items.length - 1) {
            const nextStart = items[index + 1].startFrame;
            dimFactor = interpolate(
              frame,
              [nextStart, nextStart + 15],
              [1, 0.45],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );
          }
          const finalOpacity = baseOpacity * dimFactor;

          // Checkmark animations
          const checkCircleScale = spring({
            fps,
            frame: frame - item.startFrame - 8,
            config: { damping: 12, mass: 0.8 },
          });

          const checkPathProgress = spring({
            fps,
            frame: frame - item.startFrame - 12,
            config: { damping: 14 },
          });
          const clampedCheckPathProgress = Math.max(
            0,
            Math.min(1, checkPathProgress)
          );

          const checkmarkPath = "M 7 13 L 11 17 L 18 8";
          const pathEvolution = evolvePath(
            clampedCheckPathProgress,
            checkmarkPath
          );

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                gap: 40 * s,
                opacity: finalOpacity,
                transform: `translateY(${slideY}px)`,
                transition: "none",
              }}
            >
              <div
                style={{
                  position: "relative",
                  width: squareSize,
                  height: squareSize,
                  flexShrink: 0,
                  transition: "none",
                }}
              >
                {/* White Container Square */}
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    backgroundColor: "white",
                    borderRadius: 32 * s,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: `0 ${12 * s}px ${36 * s}px rgba(0, 0, 0, 0.25)`,
                    transition: "none",
                  }}
                >
                  <div
                    style={{
                      width: 80 * s,
                      height: 80 * s,
                      transition: "none",
                    }}
                  >
                    {item.icon === "target" && <TargetIcon color={iconColor} />}
                    {item.icon === "chart" && <ChartIcon color={iconColor} />}
                    {item.icon === "path" && <PathIcon color={iconColor} />}
                  </div>
                </div>

                {/* Overlapping Checkmark Circle */}
                <div
                  style={{
                    position: "absolute",
                    top: -16 * s,
                    left: -16 * s,
                    width: 52 * s,
                    height: 52 * s,
                    backgroundColor: accentColor,
                    borderRadius: "50%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${checkCircleScale})`,
                    boxShadow: `0 ${8 * s}px ${20 * s}px rgba(0, 0, 0, 0.35)`,
                    transition: "none",
                  }}
                >
                  <svg
                    width="60%"
                    height="60%"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="white"
                    strokeWidth="3.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    style={{ overflow: "visible", transition: "none" }}
                  >
                    <path d={checkmarkPath} {...pathEvolution} />
                  </svg>
                </div>
              </div>

              {/* Text Item */}
              <div
                style={{
                  flex: 1,
                  fontSize: 44 * s,
                  fontWeight: 700,
                  color: "white",
                  lineHeight: 1.25,
                  letterSpacing: "-0.02em",
                  textShadow: `0 ${2 * s}px ${12 * s}px rgba(0, 0, 0, 0.6), 0 ${1 * s}px ${3 * s}px rgba(0, 0, 0, 0.8)`,
                  transition: "none",
                }}
              >
                {item.text}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

